// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;

import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyPredicateWorkSplit.Group;
import org.junit.jupiter.api.Test;

class LmdbAdjacencyPredicateWorkSplitTest {

	@Test
	void tilesThePredicateCatalogWithoutGaps() {
		long[] weights = { 5, 17, 3, 900, 4, 4, 60, 1 };
		Group[] groups = LmdbAdjacencyPredicateWorkSplit.plan(weights, 6);

		assertContiguousTiling(groups, weights.length);
	}

	@Test
	void uniformWeightsSplitEvenly() {
		long[] weights = new long[12];
		Arrays.fill(weights, 100);

		Group[] groups = LmdbAdjacencyPredicateWorkSplit.plan(weights, 4);

		assertContiguousTiling(groups, weights.length);
		assertThat(groups).hasSize(4);
		for (Group group : groups) {
			assertThat(group.size()).isEqualTo(3);
			assertThat(group.partitions()).isEqualTo(1);
			assertThat(group.weight()).isEqualTo(300);
		}
	}

	/**
	 * The regression this class exists for: one predicate holding most of the statements must be isolated and
	 * subdivided instead of being handed to a single range together with its neighbours. An even split by predicate
	 * count over this input gives the heaviest range 900 of the 1000 statements, nine times the ideal share.
	 */
	@Test
	void oneHugePredicateIsIsolatedAndSubdivided() {
		long[] weights = { 10, 10, 900, 10, 10, 10, 10, 10, 10, 10, 10 };
		int targetRanges = 10;

		Group[] groups = LmdbAdjacencyPredicateWorkSplit.plan(weights, targetRanges);

		assertContiguousTiling(groups, weights.length);
		Group heavy = Arrays.stream(groups)
				.filter(group -> group.fromInclusive() == 2)
				.findFirst()
				.orElseThrow();
		assertThat(heavy.size()).isEqualTo(1);
		assertThat(heavy.partitions()).isGreaterThan(1);

		long total = Arrays.stream(weights).sum();
		double ideal = (double) total / targetRanges;
		assertThat(worstRangeWeight(groups)).isLessThanOrEqualTo(2 * ideal);
	}

	@Test
	void neverExceedsThePartitionBudget() {
		long[] weights = { 1, 1, 5_000, 1, 1, 900, 1, 3_000, 1, 1, 1, 1 };
		for (int targetRanges = 2; targetRanges <= 32; targetRanges++) {
			Group[] groups = LmdbAdjacencyPredicateWorkSplit.plan(weights, targetRanges);
			assertContiguousTiling(groups, weights.length);
			assertThat(Arrays.stream(groups).mapToInt(Group::partitions).sum())
					.as("partition budget for targetRanges=" + targetRanges)
					.isLessThanOrEqualTo(targetRanges);
		}
	}

	@Test
	void multiplePredicateGroupsAreNeverSubdivided() {
		long[] weights = { 3, 3, 3, 4_000, 3, 3, 3, 3 };
		Group[] groups = LmdbAdjacencyPredicateWorkSplit.plan(weights, 8);

		for (Group group : groups) {
			if (group.partitions() > 1) {
				assertThat(group.size()).isEqualTo(1);
			}
		}
	}

	@Test
	void degenerateInputsCollapseToOneGroup() {
		assertThat(LmdbAdjacencyPredicateWorkSplit.plan(new long[0], 8))
				.containsExactly(new Group(0, 0, 1, 0));
		assertThat(LmdbAdjacencyPredicateWorkSplit.plan(new long[] { 4, 4, 4 }, 1))
				.containsExactly(new Group(0, 3, 1, 12));
		assertThat(LmdbAdjacencyPredicateWorkSplit.plan(new long[] { 0, 0, 0 }, 8))
				.containsExactly(new Group(0, 3, 1, 0));
	}

	@Test
	void trailingLightPredicatesAreNeverDropped() {
		long[] weights = { 10_000, 1, 1, 1, 1, 1, 1, 1 };
		Group[] groups = LmdbAdjacencyPredicateWorkSplit.plan(weights, 4);

		assertContiguousTiling(groups, weights.length);
		assertThat(groups[groups.length - 1].toExclusive()).isEqualTo(weights.length);
	}

	@Test
	void contiguousBoundsNeverSubdivideAndStayBalanced() {
		long[] weights = { 5, 5, 800, 5, 5, 90, 5, 5, 80 };
		int[] bounds = LmdbAdjacencyPredicateWorkSplit.contiguousBounds(weights, 4);

		assertThat(bounds[0]).isZero();
		assertThat(bounds[bounds.length - 1]).isEqualTo(weights.length);
		for (int i = 1; i < bounds.length; i++) {
			assertThat(bounds[i]).isGreaterThan(bounds[i - 1]);
		}
		// The 800-statement predicate must be alone in its chunk instead of dragging neighbours along.
		int heavyChunk = -1;
		for (int i = 1; i < bounds.length; i++) {
			if (bounds[i - 1] <= 2 && 2 < bounds[i]) {
				heavyChunk = i - 1;
			}
		}
		assertThat(heavyChunk).isNotNegative();
		assertThat(bounds[heavyChunk + 1] - bounds[heavyChunk]).isEqualTo(1);
	}

	@Test
	void negativeWeightsAreRejected() {
		assertThatThrownBy(() -> LmdbAdjacencyPredicateWorkSplit.plan(new long[] { 1, -1 }, 4))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("nonnegative");
	}

	private static void assertContiguousTiling(Group[] groups, int predicateCount) {
		assertThat(groups).isNotEmpty();
		assertThat(groups[0].fromInclusive()).isZero();
		assertThat(groups[groups.length - 1].toExclusive()).isEqualTo(predicateCount);
		for (int i = 1; i < groups.length; i++) {
			assertThat(groups[i].fromInclusive()).isEqualTo(groups[i - 1].toExclusive());
		}
	}

	private static double worstRangeWeight(Group[] groups) {
		double worst = 0;
		for (Group group : groups) {
			worst = Math.max(worst, (double) group.weight() / group.partitions());
		}
		return worst;
	}
}
